package com.bautruc.ecommerce.chat.api;
import com.bautruc.ecommerce.chat.api.request.ChatMessageRequest;import com.bautruc.ecommerce.chat.application.ChatService;import com.bautruc.ecommerce.common.logging.LogContext;import com.bautruc.ecommerce.common.response.ApiResponse;import com.bautruc.ecommerce.common.time.BusinessClock;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/chat") public class AdminChatController {private final ChatService chat;private final BusinessClock clock;public AdminChatController(ChatService chat,BusinessClock clock){this.chat=chat;this.clock=clock;}@GetMapping("/conversations")public ApiResponse<ChatService.ConversationPage> list(@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ok(chat.adminList(status,page,size));}@GetMapping("/conversations/{id}")public ApiResponse<ChatService.ThreadView> thread(@PathVariable Long id){return ok(chat.adminThread(id));}@PostMapping("/conversations/{id}/messages")public ApiResponse<ChatService.ThreadView> reply(@PathVariable Long id,@Valid @RequestBody ChatMessageRequest req){return ok(chat.reply(id,req));}@PatchMapping("/conversations/{id}/close")public ApiResponse<ChatService.ThreadView> close(@PathVariable Long id){return ok(chat.adminClose(id));}private <T>ApiResponse<T> ok(T d){return ApiResponse.success(d,null,clock.businessNow().toOffsetDateTime(),LogContext.currentCorrelationId());}}
